import sys
from functools import lru_cache

def solution(input_str):
    """
    Solves the chip game problem where First player wants to meet both chips,
    and Second player wants to glue squares to prevent this.

    Args:
        input_str: String containing n, m, x1, y1, x2, y2

    Returns:
        "First\n" if First player wins, "Second\n" otherwise
    """
    parts = input_str.strip().split()
    n, m = int(parts[0]), int(parts[1])
    x1, y1 = int(parts[2]), int(parts[3])
    x2, y2 = int(parts[4]), int(parts[5])

    # Use 0-based indexing internally
    p1 = (x1 - 1, y1 - 1)
    p2 = (x2 - 1, y2 - 1)

    def get_neighbors(pos):
        r, c = pos
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                neighbors.append((nr, nc))
        return neighbors

    def is_win_state(p1_pos, p2_pos):
        return p1_pos == p2_pos

    def is_stuck_state(p1_pos, p2_pos, glued):
        return p1_pos in glued and p2_pos in glued and p1_pos != p2_pos

    @lru_cache(maxsize=None)
    def can_first_win(p1_pos, p2_pos, glued, second_turn=False):
        """
        Returns True if First can win from current state with optimal play.

        State variables:
        p1_pos: position of chip 1
        p2_pos: position of chip 2  
        glued: frozenset of glued positions
        second_turn: Boolean indicating whose turn it is
        """

        # If both chips are on same square, First wins immediately
        if p1_pos == p2_pos:
            return True

        # Prepare glue state if needed (second player turns)
        current_glued = glued if isinstance(glued, frozenset) else frozenset(glued)

        # Check if both chips are glued (Stuck in different squares) -> Second wins
        if p1_pos in current_glued and p2_pos in current_glued and p1_pos != p2_pos:
            return False

        if second_turn:
            # Second player's turn: place glue on any valid empty square
            # Best strategy for Second: block First player's winning moves
            empty_squares = []
            for r in range(n):
                for c in range(m):
                    if (r, c) not in current_glued and (r, c) != p1_pos and (r, c) != p2_pos:
                        # Can move glue here strategically
                        empty_squares.append((r, c))

            if not empty_squares:
                return False  # No moves available, First should lose

            for glue_pos in empty_squares:
                new_glued = current_glued | {glue_pos}
                if not can_first_win(p1_pos, p2_pos, new_glued, False):
                    # If any move leads to Second winning for First, Second will choose it
                    return True

            return False  # All gluing choices lead to First winning

        else:
            # First player's turn: move one chip
            # Try moving chip 1
            if p1_pos not in current_glued:
                for new_pos in get_neighbors(p1_pos):
                    # Can't move to occupied square by other chip
                    if new_pos != p2_pos:
                        new_glued = current_glued
                        if new_pos in current_glued:
                            new_glued = new_glued | {p1_pos}  # Chip gets glued
                        else:
                            new_glued = new_glued | {new_pos}

                        if can_first_win(new_pos, p2_pos, new_glued, True):
                            return True

            # Try moving chip 2
            if p2_pos not in current_glued:
                for new_pos in get_neighbors(p2_pos):
                    if new_pos != p1_pos:
                        new_glued = current_glued
                        if new_pos in current_glued:
                            new_glued = new_glued | {p2_pos}  # Chip gets glued
                        else:
                            new_glued = new_glued | {new_pos}

                        if can_first_win(p1_pos, new_pos, new_glued, True):
                            return True

            return False

    # Initialize the first move
    result = can_first_win(p1, p2, frozenset(), second_turn=False)

    return "First\n" if result else "Second\n"

