                adj.append((None, value))  # parent is None, value is the leaf value

        # Build parent array and compute subtree info
        parent = [None] * n
        children = [[] for _ in range(n)]
        leaf_values = [None] * n

        for p_idx, (left, right) in enumerate(adj):
            if left is not None:
                parent[left] = p_idx
                children[p_idx].append(left)
                if right is not None:
                    parent[right] = p_idx
