        # Solve using DP/memoization
        memo = {}

        def compute(node_idx, is_pieguy_turn):
            # is_pieguy_turn: True if it's Pieguy's turn to make a move in this subtree
            if node_idx is None:
                return node_idx

            # Check memo
            state = (node_idx, is_pieguy_turn)
            if state in memo:
                return memo[state]

            # Check if node is a leaf
            if parent[node_idx] is None:
                memo[state] = leaf_values[node_idx]
                return leaf_values[node_idx]

            # Internal node - compute result from children
            left_result = compute(children[node_idx][0], False)
            right_result = compute(children[node_idx][1], False)

            # Calculate the max value from subtree
            # Internal nodes follow the max/min logic based on subtree size
            return max(left_result, right_result)

        memo.clear()
        result = compute(0, False)

        # Double-check with actual problem structure
