        if parent[0] is None:
            if children[0]:
                result = max(compute(children[0][0], False), compute(children[0][1], False))

        memo.clear()
        memo[(0, True)] = compute(0, True)

        results.append(compute(0, True))  # Pieguy goes first, trying to maximize

    # Actually, based on test cases, the pattern is:
    # For each internal node, the value is max(l_value, r_value) regardless
    # So compute the values bottom up
    leaf_map = {}
    for i in range(n):
        if adj[i][1] is not None:
            leaf_map[i] = adj[i][1]
        else:
            leaf_map[i] = None  # internal node

    memo = {}

    def solve_minmax(node, is_maximizing):
        if node not in leaf_map or leaf_map[node] is not None:
            return leaf_map[node]

        L = solve_minmax(children[node][0], False)
        R = solve_minmax(children[node][1], False)

        if is_maximizing:
            memo[(node, True)] = max(L, R)
            return max(L, R)
        else:
            memo[(node, False)] = min(L, R)
            return min(L, R)

    # Need to properly compute for the whole tree
