        leaf_val = [0] * n
        left_child = [-1] * n
        right_child = [-1] * n

        for i in range(n):
            parts = lines[idx].strip().split()
            idx += 1
            if parts[0] == '-1':
                l, r = int(parts[1]), int(parts[2])
                left_child[i] = l
                right_child[i] = r
                is_leaf[i] = False
            else:
                leaf_val[i] = int(parts[0])
                is_leaf[i] = True

        # Compute result from leaves up
        def dfs(u, is_pieguy):
            if is_leaf[u]:
                return leaf_val[u]

            L = dfs(left_child[u], not is_pieguy)
            R = dfs(right_child[u], not is_pieguy)

            if is_pieguy:
                return max(L, R)
            else:
                return min(L, R)

        res = dfs(0, True)
        results.append(res)

    return '\n'.join(map(str, results))


