class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, capacity):
        self.graph[u].append([v, capacity, len(self.graph[v]), 0])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1, 0])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v, cap, rev, flow in self.graph[u]:
                if cap - flow > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev, current_flow = self.graph[u][i]
            if self.level[u] < self.level[v] and cap - current_flow > 0:
                pushed = self.dfs(v, t, min(flow, cap - current_flow), ptr)
                if pushed > 0:
                    self.graph[u][i] = [v, cap, rev, current_flow + pushed]
                    self.graph[v][rev] = [u, cap, len(self.graph[u]), current_flow + pushed]
                    return pushed
        return 0

    def get_flow(self, u, v):
        for edge in self.graph[u]:
            if edge[0] == v:
                return edge[3]
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow


