def solution(input_str):
    lines = input_str.strip().split('\n')

    if not lines:
        return "Lillebror\n"

    # Parse the grid
    grid = []
    for line in lines:
        if line.strip():
            grid.append(line.strip().split())

    # Extract chocolate positions as (row, col) tuples
    chocolates = []
    max_col = -1
    for row_idx, row in enumerate(grid):
        if row:
            for col_idx, val in enumerate(row):
                if val == 'O':
                    chocolates.append((row_idx, col_idx))

    if not chocolates:
        return "Lillebror\n"

    # Memoization cache
    cache = {}

    def make_state_from_pos_set(pos_set):
        """Convert set of positions to canonical tuple representation"""
        if pos_set:
            return tuple(tuple(p) for p in sorted(pos_set))
        return tuple()

    @lru_cache(maxsize=None)
    def can_win(frozen_pos_set):
        """Returns True if the current player has a winning strategy from this state"""
        pos_set = set()
        if frozen_pos_set:
            for p in frozen_pos_set:
                if all(isinstance(x, int) for x in p):
                    pos_set.add(tuple(p))

        if not pos_set:
            return False  # No move possible, current player loses

        # Group chocolates by the 3 hexagonal directions
        # In a proper hexagonal grid:
        # - Horizontal: same row
        # - Left-slanting / diagonal /0: row+col = constant
        # - Right-slanting / diagonal /1: col-row = constant

        all_lines = []

        # Horizontal lines (same row)
        rows = {}
        for p in pos_set:
            r, c = p
            if r not in rows:
                rows[r] = []
            rows[r].append(p)
        for r, cells in rows.items():
            all_lines.append(cells)

        # Left-slanting diagonals (row+col constant)
        diag_right = {}
        for p in pos_set:
            r, c = p
            k = (r + c)
            if k not in diag_right:
                diag_right[k] = []
            diag_right[k].append(p)
        for k, cells in diag_right.items():
            all_lines.append(cells)

        # Right-slanting diagonals (col-row constant)
        diag_left = {}
        for p in pos_set:
            r, c = p
            k = (c - r)
            if k not in diag_left:
                diag_left[k] = []
            diag_left[k].append(p)
        for k, cells in diag_left.items():
            all_lines.append(cells)

        # Try all possible moves
        # A move consists of eating 2+ chocolates on the same line
        for line in all_lines:
            if len(line) >= 2:
                # Try removing at least 2 consecutive chocolates
                n = len(line)
                for i in range(n):
                    for j in range(i + 1, n + 1):
                        if j - i < 2:
                            continue
                        removed = tuple(line[i:j])
                        remaining_pos_set = pos_set - set(removed)

                        # Convert to frozenset for hashing
                        remaining_frozen = frozenset(remaining_pos_set)

                        # If removing this group leads to opponent losing, we win
                        if not can_win(remaining_frozen):
                            return True

        # No winning move found
        return False

    initial_state = frozenset([tuple(p) for p in chocolates])
    result = can_win(initial_state)

    if result:
        return "Karlsson\n"
    else:
        return "Lillebror\n"

