def is_geometric(sequence):
    n = len(sequence)
    if n <= 1:
        return True
    if n == 2:
        return True

    # If all elements are 0, it's a GP
    if all(x == 0 for x in sequence):
        return True

    count = 0
    for x in sequence:
        count += x == 0

    first_nonzero = None
    for i in range(n):
        if sequence[i] != 0:
            first_nonzero = i
            break

    # If there are non-zero elements, all elements before the first non-zero 
    # and all elements after must be consistent with GP (with c = first_nonzero)
    # This means if sequence[first_nonzero] != 0, all earlier must be 0

    # For the sequence to be a GP with some non-zero value:
    # All leading zeros are OK, then non-zeros must form GP

    # Find first non-zero pair to establish ratio
    ratio_num = None
    ratio_den = None

    for i in range(first_nonzero, n - 1):
        if sequence[i] != 0 and sequence[i+1] != 0:
            ratio_num = sequence[i+1]
            ratio_den = sequence[i]
            ratio_established = True
            break

    if not ratio_established:
        # If we never found two consecutive non-zeros, check if we have
        # a single non-zero (then it's GP) or all zeros
        if sequence[first_nonzero] == 0:
            return True  # all zeros
        else:
            # One non-zero, rest are zeros - check if non-zero is at end
            # [0,0,1], [0,0,0,1] - are these GPs? 
            # a[0]=0, a[1]=0, a[2]=1: For GP with a[0]=0, all must be 0. Not valid.
            # Actually [0,0,1] is not a valid GP
            return False

    for i in range(first_nonzero, n - 1):
        a = sequence[i]
        b = sequence[i+1]
        if a == 0:
            if b != 0:
                return False
        else:
            if b == 0:
                return False
            if ratio_num * a != ratio_den * b:
                return False

    return True


