def is_balanced(seq):
    balance = {}
    for x in seq:
        if x > 0:
            balance[x] = balance.get(x, 0) + 1
        else:
            if x not in balance or balance[x] == 0:
                return False
            balance[x] -= 1
        if balance[x] == 0:
            del balance[x]
    return len(balance) == 0

