    threshold = math.ceil(math.sqrt(n))

    # DFS to find a cycle of length >= threshold
    visited = [0] * (n + 1)  # 0 = unvisited, 1 = in current stack
    parent = [0] * (n + 1)
    stack = []
    result_cycle = []

    def dfs(start):
        stack.append(start)
        visited[start] = 1
        parent[start] = start

        for v in adj[start]:
            if v == parent[start]:
                continue

            if visited[v] == 0:
                parent[v] = start
                result = dfs(v)
                if result is not None:
                    return result
            elif visited[v] == 1 and v != parent[start]:
                # Found back edge, cycle
                idx = stack.index(v)
                cycle = stack[idx:] + [v]
                if v not in stack:
                    cycle.append(v)
                if len(cycle) >= threshold:
