    adj = [[] for _ in range(n + 1)]
    for i, (u, v) in enumerate(edge_list):
        adj[u].append((v, i + 1))
        adj[v].append((u, i + 1))

    min_cuts = [-1]
    best_edges = []

    def calculate_boundary(subtree):
        """Calculate boundary edges for a given subtree."""
        boundary = set()
        for u in subtree:
            for v, edge_id in adj[u]:
                if v not in subtree:
                    boundary.add(edge_id)
        return boundary

