    while len(suffix_to_year) < 10000 and year <= 100000:
        year_str = str(year)
        for length in range(1, len(year_str) + 1):
            suffix = year_str[-length:]
            if suffix not in used:
                used.add(suffix)
                suffix_to_year[suffix] = year
                break
        year += 1

    # Process each abbreviation
    results = []
    for abbr in abbreviations:
        if "'" in abbr:
            # Extract suffix after IAO'
            suffix = abbr.split("'")[1]
            if suffix in suffix_to_year and suffix_to_year[suffix] <= 100000:
                results.append(str(suffix_to_year[suffix]))
            else:
                # If not in our precomputed range, search for the year
                for test_year in range(100000, 10000000):
                    test_str = str(test_year)
                    for length in range(1, len(test_str) + 1):
                        check_suffix = test_str[-length:]
                        if check_suffix == suffix:
                            # Check if this suffix would be selected for this year
                            is_valid = True
                            for other_year in range(1989, test_year + 1):
                                other_str = str(other_year)
                                for ol in range(1, len(other_str) + 1):
                                    ot = other_str[-ol:]
                                    if ot != suffix:
                                        continue
                                    # Would this suffix have been used by an earlier year?
                                    if ol < length and test_str.endswith(suffix):
                                        is_valid = False
                                        break
                            if is_valid:
                                results.append(str(test_year))
                                break
                    if any(r.endswith(suffix) or suffix in r for r in results):
                        break
        else:
            results.append("0")

    return '\n'.join(results)

import math
import random

def dist_sq(p1, p2):
    return (p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2

def dist(p1, p2):
    return math.sqrt(dist_sq(p1, p2))

def gauss_elimination(A, B):
    """Solve Ax = B using Gaussian elimination with partial pivoting"""
    n = len(A)
    for i in range(n):
        max_row = i
        for k in range(i+1, n):
            if abs(A[k][i]) > abs(A[max_row][i]):
                max_row = k
        A[i], A[max_row] = A[max_row], A[i]
        B[i], B[max_row] = B[max_row], B[i]

        if abs(A[i][i]) < 1e-10:
            continue

        for k in range(i+1, n):
            factor = A[k][i] / A[i][i]
            for j in range(i, n+1):
                A[k][j] -= factor * A[i][j]
            B[k] -= factor * B[i]

    x = [0.0] * n
    for i in range(n-1, -1, -1):
        if abs(A[i][i]) < 1e-10:
            x[i] = 0.0
        else:
            x[i] = B[i]
            for j in range(i+1, n):
                x[i] -= A[i][j] * x[j]
            x[i] /= A[i][i]
    return x

