def compute_3d_circumcenter(p0, p1, p2):
    # Solve for circumcenter using perpendicular bisector equations
    eq = [[0.0]*4, [0.0]*4, [0.0]*4]
    B = [0.0, 0.0, 0.0]

    # (x - p0)^2 = (x - p1)^2 => 2(x)(p1 - p0) = p1^2 - p0^2
    for i in range(3):
        for j in range(3):
            eq[i][j] = p1[j] - p0[j] if i == j else 0.0
        B[0] = (p1[0]**2 - p0[0]**2 + p1[1]**2 - p0[1]**2 + p1[2]**2 - p0[2]**2) / 2.0

    for i in range(3):
        for j in range(3):
            eq[i+1][j] = p2[j] - p0[j] if i+1 == j else 0.0
        B[1] = (p2[0]**2 - p0[0]**2 + p2[1]**2 - p0[1]**2 + p2[2]**2 - p0[2]**2) / 2.0
    B[2] = 0.0

    # Gaussian elimination
    A = [row[:] for row in eq]
    for i in range(3):
        max_row = i
        for k in range(i+1, 3):
            if abs(A[k][i]) > abs(A[max_row][i]):
                max_row = k
        A[i], A[max_row] = A[max_row], A[i]
        B[i], B[max_row] = B[max_row], B[i]

        if abs(A[i][i]) < 1e-12:
            return [0.0, 0.0, 0.0, 0.0]

        for k in range(i+1, 3):
            f = A[k][i] / A[i][i]
            A[i] = [A[i][j] - f * A[i][j] for j in range(3)]
            B[k] -= f * B[i]

    # Back substitution
    x = [0.0, 0.0, 0.0]
    for i in range(2, -1, -1):
        abs_A_ii = abs(A[i][i])
        if abs_A_ii < 1e-12:
            val = 0.0
        else:
            val = B[i]
            for j in range(i+1, 3):
                val -= A[i][j] * x[j]
            val /= A[i][i]
        x[i] = val

    r = dist_sq(x, p0)
    return [x[0], x[1], x[2], math.sqrt(max(0.0, r))]


def welzl_full(points, R):
    if len(points) == 0 or len(R) == 4:
        return sphere_from_boundary(R)

    p = points.pop()
    try:
        D = welzl_full(points, R)
    finally:
        points.append(p)

    if dist_sq(p, D[:3]) <= D[3]**2:
        return D
    else:
        return welzl_full(points, R + [p])


