import math

def solution(input_str):
    parts = input_str.strip().split()
    if len(parts) < 2:
        return '0\n'

    l, r = int(parts[0]), int(parts[1])

    if l > r:
        return '0\n'

    if l < 1:
        l = 1

    # We need to find primes in [l, r] that are 2 or ≡ 1 (mod 4)
    # These are exactly the primes that can be written as sum of two positive squares
    # (based on Fermat's theorem on sums of two squares)

    sqrt_r = int(math.isqrt(r))

    # Generate primes up to sqrt_r using sieve
    if sqrt_r < 2:
        primes = []
    else:
        is_prime_small = bytearray([1]) * (sqrt_r + 1)
        is_prime_small[0] = 0
        is_prime_small[1] = 0
        primes = []
        for i in range(2, sqrt_r + 1):
            if is_prime_small[i]:
                primes.append(i)
                # Step i^2, then step i for remaining
                for j in range(i * i, sqrt_r + 1, i):
                    is_prime_small[j] = 0

    # Segmented sieve for range [l, r]
    size = r - l + 1
    is_prime_range = bytearray([1]) * size

    # 1 is not prime
    if l == 1:
        is_prime_range[0] = 0

    # Mark composites using primes up to sqrt(r)
    for p in primes:
        # Find first multiple of p >= l
        if l <= p:
            first = p * 2  # Skip p itself since it's prime
        else:
            first = l + (p - l % p) % p

        # Mark multiples of p in the range
        if first <= r:
            for idx in range(first - l, r - l + 1, p):
                is_prime_range[idx] = 0

    # Count primes that are 2 or ≡ 1 (mod 4)
    count = 0
    for i in range(l, r + 1):
        if is_prime_range[i - l]:
            if i == 2 or i % 4 == 1:
                count += 1

    return str(count) + '\n'


