    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    total_sum = sum(a)

    if total_sum == 0:
        return '0'
    if total_sum == 1:
        return '-1'

    # Find all divisors of total_sum
    divisors = set()
    i = 2
    limit = int(total_sum ** 0.5)
    while i * i <= total_sum:
        if total_sum % i == 0:
            divisors.add(i)
            divisors.add(total_sum // i)
        i += 1

    # Find prefix sums
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + a[i]

    # Remove last prefix sum since it's always divisible by total_sum (and thus by k when k|total_sum)
    prefix_rem = prefix[:n]  # Only the first n-1 prefix sums

    min_cost = float('inf')

    for k in divisors:
        if k == 1:
            continue
        cost = 0
        for p in prefix_rem:
            r = p % k
            if r > k - r:
                r = k - r
            cost += r
        if cost < min_cost:
            min_cost = cost

    return str(min_cost)

