    n = int(lines[0])
    contacts = lines[1:n+1]
    predictions = list(map(int, lines[n+1].split()))

    # Convert contacts to a matrix
    contact_matrix = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(int(contacts[i][j]))
        contact_matrix.append(row)

    # Function to calculate messages received for a given subset
    def count_messages(selected):
        counts = []
        for i in range(n):
            count = 0
            for j in range(n):
                if selected[j] and contact_matrix[i][j] == 1:
                    count += 1
            counts.append(count)
        return counts

    # Check if a subset satisfies the conditions (all different from predictions)
    def is_valid(selected):
        counts = count_messages(selected)
        for i in range(n):
            if counts[i] == predictions[i]:
                return False
        return True

    # Generate all possible subsets using recursion with pruning
    all_indices = list(range(n))

    def backtrack(start, selected):
        # Pruning: check if we've already exceeded possible valid combinations
        # For optimization, check if current prefix already violates some counts

        if start == n:
            if is_valid(selected):
                return selected

        # Try including current index
        for i in range(start, n):
            # Add employee (i+1) to selected
            new_selected = list(selected) + [i]
            result = backtrack(i + 1, new_selected)
            if result:
                return result
        return None

    result = backtrack(0, [])

    if result is None:
        return "-1"

    # Format output
    m = len(result)
    indices = " ".join(str(i + 1) for i in range(m))
    return f"{m}\n{indices}"

