import sys

def solution(input_str):
    """
    Process input, make queries if interactive mode, or compute directly.
    Returns the answer string.
    """
    # For direct solution (test cases)
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()

    if not first_line:
        return ""

    n, m = int(first_line[0]), int(first_line[1])

    # Parse matrix from input
    matrix = []
    idx = 1
    for r in range(n):
        row = []
        while len(row) < m and idx < len(lines):
            if idx < len(lines):
                parts = list(map(int, lines[idx].split()))
                row.extend(parts)
                idx += 1
        matrix.append(row)

    # Find all valid (r, c) pairs
    valid_pairs = []

    row_divs = [r for r in range(1, n + 1) if n % r == 0]
    col_divs = [c for c in range(1, m + 1) if m % c == 0]

    def get_block_tuple(block_r, block_c, r, c):
        """Get tuple representation of a block"""
        result = []
        for rr in range(block_r * r, (block_r + 1) * r):
            for cc in range(block_c * c, (block_c + 1) * c):
                result.append(matrix[rr][cc])
        return tuple(result)

    # Check each (r, c) pair
    for r in row_divs:
        for c in col_divs:
            # Get reference block (0, 0)
            ref = get_block_tuple(0, 0, r, c)
            all_equal = True
            num_row_blocks = n // r
            num_col_blocks = m // c

            for br in range(num_row_blocks):
                for bc in range(num_col_blocks):
                    if br == 0 and bc == 0:
                        continue
                    block = get_block_tuple(br, bc, r, c)
                    if block != ref:
                        all_equal = False
                        break
                if not all_equal:
                    break

            if all_equal:
                valid_pairs.append((r, c))

    # Output format
    result = ["!", str(len(valid_pairs))]
    for r, c in valid_pairs:
        result.append(f"{r} {c}")

    return "\n".join(result)


