    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:]:
        if not line.strip():
            continue
        u, v = map(int, line.split())
        adj[u].append(v)

    # BFS from each node to compute all shortest paths
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        queue = [start]
        dist[start][start] = 0
        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            for v in adj[u]:
                if dist[start][v] == float('inf'):
                    dist[start][v] = dist[start][u] + 1
                    queue.append(v)

    max_val = -1
    best_route = []

    # For smaller n, use brute force O(n^4)
    if n <= 500:
        for a in range(1, n + 1):
            for b in range(1, n + 1):
                if a == b: continue
                if dist[a][b] == float('inf'): continue
                for c in range(1, n + 1):
                    if c == a or c == b: continue
                    if dist[b][c] == float('inf'): continue
                    for d in range(1, n + 1):
                        if d == a or d == b or d == c: continue
                        if dist[c][d] == float('inf'): continue

                        total = dist[a][b] + dist[b][c] + dist[c][d]
                        if total > max_val:
                            max_val = total
                            best_route = [a, b, c, d]
    else:
        # For larger n, iterate b, c and find best a, d efficiently
        # Precompute top candidates for each node
        # For each node x, store (distance, from_node) sorted descending

        # candidates_to[x] = list of (dist[a][x], a) for all a, sorted descending
        candidates_to = []
        for i in range(1, n + 1):
            top = []
            for j in range(1, n + 1):
                if dist[j][i] != float('inf'):
                    top.append((dist[j][i], j))
            top.sort(reverse=True)
            candidates_to.append(top)

        # candidates_from[x] = list of (dist[x][d], d) for all d, sorted descending
        candidates_from = []
        for i in range(1, n + 1):
            top = []
            for j in range(1, n + 1):
                if dist[i][j] != float('inf'):
                    top.append((dist[i][j], j))
            top.sort(reverse=True)
            candidates_from.append(top)

        for b in range(1, n + 1):
            for c in range(1, n + 1):
                if b == c: continue
                if dist[b][c] == float('inf'): continue

                # Find best a ≠ b, a ≠ c
                best_a = -1
                best_a_dist = -1
                for item in candidates_to[b]:
                    d_a, a_node = item
                    if a_node == b or a_node == c:
                        continue
                    if d_a > best_a_dist:
                        best_a_dist = d_a
                        best_a = a_node
                if best_a == -1:
                    continue

                # Find best d ≠ a, d ≠ b, d ≠ c
                best_d = -1
                best_d_dist = -1
                for item in candidates_from[c]:
                    d_d, d_node = item
                    if d_node == a or d_node == b or d_node == c:
                        continue
                    if d_d > best_d_dist:
                        best_d_dist = d_d
                        best_d = d_node
                if best_d == -1:
                    continue

                total = best_a_dist + dist[b][c] + best_d_dist
                if total > max_val:
                    max_val = total
                    best_route = [best_a, b, c, best_d]

    return ' '.join(map(str, best_route))

