        # Kick-start has potential = N initially (all nodes part of inactive component)
        total = n
        remaining = n - 1

        for _ in range(len(order) - 1):
            total += remaining
            remaining -= 1

        max_potential = max(max_potential, total)

    return str(max_potential)

