        if n in memo:
            return memo[n]

        options = set()
        options.add(get_g(n - 1))

        if n % 2 == 0:
            x = n // 2
            if k == 1:
                options.add(get_g(x))
            elif k % 2 == 1:
                options.add(get_g(x))
            else:
                options.add(0)

        g = 0
        while g in options:
            g += 1

        memo[n] = g
        return g

    xor_sum = 0
    for x in a:
        xor_sum ^= get_g(x)

    return "Kevin" if xor_sum != 0 else "Nicky"


