    if len(lines) < 1:
        return '0'

    n, m = map(int, lines[0].split())
    grid = [list(lines[i+1]) for i in range(n)]

    # Build fixed color array (convert to 0-indexed, None for unpainted)
    fixed = [[None]*m for _ in range(n)]
    for r in range(n):
        for c in range(m):
            if grid[r][c] != '0':
                fixed[r][c] = int(grid[r][c]) - 1

    # Check for immediate conflicts in fixed cells within 2x2 blocks
    for r in range(n-1):
        for c in range(m-1):
            colors_in_block = set()
            for dr in range(2):
                for dc in range(2):
                    if fixed[r+dr][c+dc] is not None:
                        colors_in_block.add(fixed[r+dr][c+dc])
            if len(colors_in_block) > 4:
                pass  # shouldn't happen
            # Check if any two cells in this 2x2 have same color - riskier check
            cells_in_block = []
            for dr in range(2):
                for dc in range(2):
                    if fixed[r+dr][c+dc] is not None:
                        cells_in_block.append((r+dr, c+dc, fixed[r+dr][c+dc]))
            for i in range(len(cells_in_block)):
                for j in range(i+1, len(cells_in_block)):
                    if cells_in_block[i][2] == cells_in_block[j][2]:
                        return '0'

    # Find (a, b) pairs where the formula (a*r + b*c + offset) mod 4
    # produces all 4 distinct values in any 2x2 block
    valid_ab = []
    for a in range(4):
        for b in range(4):
            if a == 0 or b == 0:
                continue
            vals = set()
            for dr in range(2):
                for dc in range(2):
                    vals.add((a * dr + b * dc) % 4)
            if len(vals) == 4:
                valid_ab.append((a, b))

    # Try each valid parameter combination
    for a, b in valid_ab:
        for offset in range(4):
            valid = True
            # Check against pre-colored cells
            for r in range(n):
                for c in range(m):
                    if fixed[r][c] is not None:
                        computed_val = (a * r + b * c + offset) % 4
                        if computed_val + 1 != fixed[r][c]:
                            valid = False
                            break
                if not valid:
                    break

            if valid:
                # Build the colored grid
                result = []
                for r in range(n):
                    row_str = [str((a * r + b * c + offset) % 4 + 1) for c in range(m)]
                    result.append(''.join(row_str))
                return '\n'.join(result)

    return '0'


