import itertools
import random

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, r = map(int, lines[0].split())

    # Generate all valid integer points within radius r
    valid_points = []
    for x in range(-r, r+1):
        for y in range(-r, r+1):
            if x*x + y*y <= r*r:
                valid_points.append((x, y))

    def score(config):
        """Calculate sum of squared distances between all tower pairs"""
        s = 0
        for i in range(len(config)):
            for j in range(i+1, len(config)):
                s += (config[i][0] - config[j][0])**2 + **config[i][1] - config[j][1]**2
        return s

    best_score = -1
    best_config = None

    # Try different sizes
    iteration_count = 50 if n >= 5 else 100

    for _ in range(iteration_count):
        if n <= 8 and n <= 6:
            # Exhaustive search for small n
            for p_tuple in itertools.permutations(range(len(valid_points)), n):
                config = [valid_points[i] for i in p_tuple]
                current_score = score(config)
                if current_score > best_score:
                    best_score = current_score
                    best_config = config
        else:
            # Greedy with local search for larger n
            config = [random.choice(valid_points) for _ in range(n)]

            # Local search - try all swaps
            improved = True
            while improved:
                improved = False
                old_score = score(config)
                for i in range(n):
                    for j in range(i+1, n):
                        new_config = list(config)
                        new_config[i], new_config[j] = new_config[j], new_config[i]
                        new_score = score(new_config)
                        if new_score > old_score:
                            config = new_config
                            improved = True
                            best_score = score(config)
                            best_config = config
                            break
                    if improved:
                        break

            if best_score is None or score(config) > best_score:
                best_score = score(config)
                best_config = config

    # Output result
    result = [str(best_score)]
    for x, y in best_config:
        result.append(f"{x} {y}")
    return '\n'.join(result)

