    min_cost = INF

    # Collect candidate divisors from each ai, ai+1, ai-1
    candidates = set()
    for x in ai:
        if x > 1:
            candidates.add(x)
        if x + 1 > 1:
            candidates.add(x + 1)
        if x - 1 > 1:
            candidates.add(x - 1)

    # Add 2 as a universal candidate
    candidates.add(2)

    for d in candidates:
        if d <= 1:
            continue

        # Compute prefix cost: number of elements in ai[0:i] not divisible by d
        prefix_bad = [0] * (n + 1)
        for i in range(n):
            prefix_bad[i + 1] = prefix_bad[i] + (1 if ai[i] % d != 0 else 0)

        # Compute suffix cost: number of elements in ai[n-i:n] not divisible by d
        suffix_bad = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix_bad[i] = suffix_bad[i + 1] + (1 if ai[i] % d != 0 else 0)

        # Option 1: Keep only prefix [0, i-1], remove [i, n-1] (length n-i >= 1)
        for i in range(1, n + 1):
            cost = prefix_bad[i] * b + (n - i) * a
            if cost < min_cost:
                min_cost = cost

        # Option 2: Keep only suffix [j, n-1], remove [0, n-j] (length n-j >= 1)
        for j in range(1, n + 1):
            cost = suffix_bad[n - j] * b + (n - j) * a
            if cost < min_cost:
                min_cost = cost

        # Option 3: Keep both prefix [0, i-1] and suffix [j, n-1], remove [i, j-1]
        # where 0 <= i <= j <= n and length of removed segment (j-i) >= 1
        # We can optimize this: for each i and j, cost = prefix_bad[i] * b + suffix_bad[n-j] * b + (j-i) * a
        # This is O(n^2) per d which is too slow

        # To optimize: iterate on the length of removed segment (len_rem = j-i >= 1)
        # and on i (prefix length), then j = i + len_rem
        for i in range(0, n):
            for j in range(i + 1, n + 1):
                cost = prefix_bad[i] * b + suffix_bad[n - j] * b + (j - i) * a
                if cost < min_cost:
                    min_cost = cost

    # If no valid d found (shouldn't happen since candidates include 2), return min_cost calculated with no changes
    if min_cost == INF:
        return str(0 + '\n')

    return str(min_cost + '\n')

