        attempt_responses.append(response)

    # Precompute masks for each bit position
    # Which attempts match at each position?
    position_masks = []
    for pos in range(n):
        mask = [(1 << (attempts[i][0] >> pos & 1)) for i in range(m)]
        position_masks.append([mask] * 2)  # Will be used as lookup

    def backtrack(pos):
        nonlocal count

        # Pruning: check if current state can lead to valid solution
        if pos == n:
            # All positions filled, verify all constraints
            for (target_attempt, response) in attempts_int:
                matches = 0
                for bit in range(n):
                    if (code[bit] == target_attempt >> bit & 1):
                        matches += 1
                if matches != response:
                    return
            count += 1
            return

        # Try both bit values
        for bit in [0, 1]:
            code[pos] = bit

            # Check for each attempt if current state is still valid
            possible = True
            for (target_attempt, response) in attempts_int:
                # Count matches so far
                current_matches = sum(1 for b in range(pos) if code[b] == (target_attempt >> b & 1))

                # Check if we've already exceeded or will inevitably miss target
                if current_matches > response:
                    possible = False
                    break

                # Calculate max possible matches from remaining positions
                remaining = n - pos
                max_additional = 0
                for b in range(pos, n):
                    if code[b] == (target_attempt >> b & 1):
                        max_additional += 1

                if current_matches + max_additional < response:
                    possible = False
                    break

            if possible:
                backtrack(pos + 1)

    backtrack(0)
    return str(count)

