def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    vertices = []
    for i in range(n):
        vertices.append(list(map(int, lines[i + 1].split())))

    MOD = 1000000007

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_segment(p, a, b):
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and \
               min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    def segments_intersect(p1, p2, p3, p4):
        """Check if two segments properly intersect (not just touching at endpoints)."""
        cp1 = cross_product(p3, p4, p1)
        cp2 = cross_product(p3, p4, p2)
        cp3 = cross_product(p1, p2, p3)
        cp4 = cross_product(p1, p2, p4)

        if cp1 == 0 or cp2 == 0:
            return on_segment(cp1, p3, p4) or on_segment(cp2, p3, p4)
        if cp3 == 0 or cp4 == 0:
            return on_segment(cp3, p1, p2) or on_segment(cp4, p1, p2)

        return (cp1 * cp2 < 0) and (cp3 * cp4 < 0)

    def is_valid_diagonal(i, j):
        """Check if diagonal (i, j) is valid (doesn't intersect polygon edges)."""
        if j <= i:
            return False

        p1, p2 = vertices[i], vertices[j]

        # Check if diagonal intersects any polygon edge
        for k in range(n):
            if k == i or k == j:
                continue
            pk = vertices[k]
            next_k = (k + 1) % n
            next_pk = vertices[next_k]

            if k == i or k == j or next_k == i or next_k == j:
                continue

            if segments_intersect(p1, p2, pk, next_pk):
                return False

        # Check if any vertex lies on the diagonal
        for k in range(n):
            if k == i or k == j:
                continue
            if on_segment(vertices[k], p1, p2):
                return False

        return True

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_triangulations(i, j):
        """Count ways to triangulate polygon from vertex i to j (in order)."""
        if j - i < 2:
            return 1

        total = 0
        for k in range(i + 1, j):
            if is_valid_diagonal(i, k) and is_valid_diagonal(k, j):
                total = (total + count_triangulations(i, k) * count_triangulations(k, j)) % MOD

        return total

    result = count_triangulations(0, n - 1)
    return f"{result}\n"

