        if idx < len(lines):
            ops_str = lines[idx]
            idx += 1
        else:
            ops_str = ''

        # Apply operations
        for op in ops_str:
            if op == 'R':
                # Shift columns right: column j gets from (j-1)%n
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        new_matrix[i][j] = matrix[i][(j - 1) % n]
                matrix = new_matrix

            elif op == 'L':
                # Shift columns left: column j gets from (j+1)%n
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        new_matrix[i][j] = matrix[i][(j + 1) % n]
                matrix = new_matrix

            elif op == 'D':
                # Shift rows down: row i gets from (i-1)%n
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        new_matrix[i][j] = matrix[(i - 1) % n][j]
                matrix = new_matrix

            elif op == 'U':
                # Shift rows up: row i gets from (i+1)%n
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        new_matrix[i][j] = matrix[(i + 1) % n][j]
                matrix = new_matrix

            elif op == 'I':
                # Inverse rows: value v at position j becomes value (j+1) at position (v-1)
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        val = matrix[i][j]
                        new_matrix[i][val - 1] = j + 1
                matrix = new_matrix

            elif op == 'C':
                # Inverse columns: value v at position (i,j) becomes value (i+1) at position (v-1,j)
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        val = matrix[i][j]
                        new_matrix[val - 1][j] = i + 1
                matrix = new_matrix

