def simulate(n, k):
    count = 0
    import itertools
    for perm in itertools.permutations(range(1, n+1)):
        ans = 0
        offset = 0
        for x in perm:
            if ans < x:
                ans = x
                offset = 0
            else:
                offset += 1
                if offset == k:
                    return perm
        if ans != n:
            count += 1
        if offset < k:
            count += 1
    return n

def solution(input_str):
    a, b, n = map(int, input_str.split())

    # Special case: if a == 1, game can go on forever
    if a == 1:
        return "Missing\n\n"

    # Memoization dictionary
    memo = {}

    def is_current_state_winning(current_a, current_b):
        if (current_a, current_b) in memo:
            return memo[(current_a, current_b)]

        # Check if current state is at or beyond threshold
        if current_a ** current_b >= n:
            return False

        # Find all valid moves (where next state has a^b < n)
        next_states = []

        # Try increasing boxes
        if (current_a + 1) ** current_b < n:
            next_states.append((current_a + 1, current_b))

        # Try increasing items
        if current_a ** (current_b + 1) < n:
            next_states.append((current_a, current_b + 1))

        if not next_states:
            # No valid moves without exceeding threshold
            result = False
        else:
            # Current player wins if can move to a state where opponent loses
            can_win = False
            for next_a, next_b in next_states:
                if not is_current_state_winning(next_a, next_b):
                    can_win = True
                    break
            result = can_win

        memo[(current_a, current_b)] = result
        return result

    # Check if starting position is winning (Stas wins if initial position is winning)
    if is_current_state_winning(a, b):
        return "Masha\n\n"  # Stas wins
    else:
        return "Stas\n\n"  # Masha wins

