def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    A = list(map(int, lines[1].split()))

    # Check if any element in initial array meets the threshold
    for x in A:
        if x >= k:
            return '0\n'

    i = 0
    while True:
        i += 1
        prefix_sum = 0
        B = []
        for x in A:
            prefix_sum += x
            B.append(prefix_sum)

        # Check if any element in transformed array meets the threshold
        for x in B:
            if x >= k:
                return str(i) + '\n'

        A = B

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n = int(lines[0])

    # Parse all queries first
    queries = []
    for i in range(1, len(lines)):
        parts = lines[i].split()
        q_type = int(parts[0])

        if q_type == 1:
            a, b = int(parts[1]), int(parts[2])
            queries.append((i + 1, 'insert', a, b))
        elif q_type == 2:
            idx = int(parts[1])
            queries.append((i + 1, 'delete', idx, None, None))
        elif q_type == 3:
            q = int(parts[1])
            queries.append((i + 1, 'query', q, None, None))

    # Collect unique q values for coordinate compression
    q_values = set()
    for q_data in queries:
        if q_data[1] == 'query':
            q_values.add(q_data[2])

    sorted_q = sorted(q_values)
    q_to_idx = {q: i for i, q in enumerate(sorted_q)}
    num_q = len(sorted_q)

    # Active pairs storage (by query number for easy removal lookup)
    active_by_query = {}  # query_num -> (a, b)
    all_inserts = {}  # stored for easy lookup during type 2 queries
    for i in range(1, n + 1):
        all_inserts[i] = (None, None)

    # Li Chao Tree structure
    class Line:
        def __init__(self, m, c, id=None, original_idx=-1):
            self.m = m
            self.c = c
            self.id = id
            self.original_idx = original_idx

        def __call__(self, x):
            return self.m * x + self.c

    class LiChaoTree:
        def __init__(self, n_q, q_values):
            self.n_q = n_q
            self.q_values = q_values
            self.tree_size = 4 * n_q
            self.tree = [None] * self.tree_size
            self.active_set = set()  # original query indices of lines in tree

        def _mid_val(self, x):
            return self.q_values[x] if 0 <= x < len(self.q_values) else 0

        def insert(self, a, b, query_idx, node=0, l=0, r=None):
            if r is None:
                r = self.n_q - 1

            if node >= self.tree_size:
                self.tree.extend([None] * self.tree_size)

            while l <= r:
                mid = (l + r) // 2
                q_mid = self.q_values[mid]

                if self.tree[node] is None:
                    self.tree[node] = Line(a, b, query_idx, node)
                    break

                curr = self.tree[node]

                # Compare at midpoint
                val_new = a * q_mid + b
                val_curr = curr.m * q_mid + curr.c

                if val_new > val_curr:
                    self.tree[node] = Line(a, b, query_idx, node)
                    a, b, query_idx = curr.m, curr.c, curr.id
                elif a * l + b > curr.m * l + curr.c and a * r + b > curr.m * r + curr.c:
                    a, b, query_idx = curr.m, curr.c, curr.id
                else:
                    break

            return l == r

        def insert_lazy(self, a, b, query_idx):
            mid = (0 + self.n_q - 1) // 2
            q_mid = self.q_values[mid] if mid < len(self.q_values) else 0

            if self.tree[0] is None or (a * q_mid + b) > self.tree[0].m * q_mid + self.tree[0].c:
                self.tree[0] = Line(a, b, query_idx)
            elif self.tree[0]:
                # Check if we can push down
                left_val = a * self.q_values[0] + b if 0 <= self.q_values[0] < self.n_q else a * q_mid + b
                right_val = a * self.q_values[-1] + b if self.q_values else a * q_mid + b

                curr_l = self.tree[0].m * self.q_values[0] + self.tree[0].c if self.q_values else a * q_mid + b
                curr_r = self.tree[0].m * self.q_values[-1] + self.tree[0].c if self.q_values else a * q_mid + b

                if left_val > curr_l and right_val > curr_r:
                    m, c, idx = self.tree[0].m, self.tree[0].c, self.tree[0].id
                    self.tree[0] = Line(a, b, query_idx)
                    self.insert_lazy(m, c, idx)

        def remove(self, query_idx):
            removed = False
            self.tree[0] = None
            node = 0
            l, r = 0, self.n_q - 1
            while l <= r:
                if self.tree[node] is not None and self.tree[node].id == query_idx:
                    removed = True
                    self.tree[node] = None
                # Try to push non-removed line down
                if self.tree[node] is not None and not removed:
                    mid = (l + r) // 2
                    has_left = 0 <= mid < self.n_q
                    has_right = l <= mid < self.n_q
                    node = node * 2 + 1 if has_left else node
                l, r = node, node
                if node >= self.tree_size * 2:
                    break
                node += 1

        def query(self, q_map_idx):
            def _query(node, l, r):
                nonlocal max_val, q_vals
                mid = (l + r) // 2
                if node >= self.tree_size or l > r:
                    return

                if self.tree[node]:
                    idx = q_to_idx.get(self.q_values[l], 0) if mid < len(self.q_values) else l
                    val = self.tree[node].m * self.q_values[indices[0]] + self.tree[node].c if indices else 0
                    max_val = max(max_val, val)
                # Stack-based traversal
                if self.tree[node]:
                    qj = self.q_values[indices[0]] if indices else self.q_values[0]
                    val = self.tree[node].m * qj + self.tree[node].c
                    max_val = max(max_val, val)
                # Traverse children
                if l != r:
                    left_idx = (l + r) // 2
                    right_idx = left_idx + 1 if l != r else l

                    # Find max at q_map_idx
                    if q_map_idx <= left_idx:
                        self._query(node * 2, l, left_idx)
                    else:
                        self._query(node * 2 + 1, left_idx + 1, r)

            max_val = float('-inf')
            _query(0, 0, self.n_q - 1)
            return max_val

    # Process queries
    output = []

    for q_num, q_type, *params in queries:
        if q_type == 'insert':
            a, b = params[0], params[1]
            active_by_query[q_num] = (a, b)
            tree.insert(a, b, q_num)
        elif q_type == 'delete':
