    phone_numbers = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        s_i, m_i = parts[0], int(parts[1])
        phone_numbers.append((s_i, m_i))

    if k == 0:
        # No speed dials, all numbers pay full length
        total_cost = sum(len(s_i) * m_i for s_i, m_i in phone_numbers)
        return str(total_cost)

    # Collect all prefixes
    prefix_savings = {}  # prefix -> {number_matches: [...]}
    all_prefixes = set()
    for s_i, m_i in phone_numbers:
        for j in range(1, len(s_i) + 1):
            p = s_i[:j]
            all_prefixes.add(p)

    # Current selected speed dial strings
    selected_prefixes = []

    for _ in range(k):
        best_reduction = -1
        best_prefix = None
        current_cost = compute_cost(phone_numbers, selected_prefixes)
        for p in all_prefixes:
            # Add p to selection temporarily
            next_prefixes = selected_prefixes + [p]
            reduction = current_cost - compute_cost(phone_numbers, next_prefixes)
            if reduction > best_reduction:
                best_reduction = reduction
                best_prefix = p

        if best_prefix is not None and best_reduction > 0:
            selected_prefixes.append(best_prefix)

    return str(compute_cost(phone_numbers, selected_prefixes))

def compute_cost(phone_numbers, selected_prefixes):
    total = 0
    for s_i, m_i in phone_numbers:
        best_match = 0
        for p in selected_prefixes:
            if s_i.startswith(p):
                best_match = max(best_match, len(p))
        total += (len(s_i) - best_match) * m_i
    return total

